class METShipmentUpdateRoutesDialog extends RunBase
{
    DialogField     metRoute;
    DialogFIeld     metRouteStopNum;
    DialogField     confirmedShipDate;

    METRoute        metRouteValue;
    METRouteStopNum metRouteStopNumValue;
    SalesShippingDateConfirmed  confirmedShipDateValue;
    METSalesOrderShipmentLoadCreationTmp    tmpTable;
    Args            args;

}

Method.Source:
public Object Dialog()
{
    Dialog dialog;

    dialog = super();

    dialog.caption( 'Route to change');

    metRoute            = dialog.addField( extendedTypeStr(METRoute), 'Change primary route to' );
    metRouteStopNum     = dialog.addField( extendedTypeStr(METRouteStopNum), 'Change route stop to' );
    confirmedShipDate   = dialog.addField( extendedTypeStr(SalesShippingDateConfirmed), 'Change confirmed shipdate to' );

    return dialog;
}

public boolean getFromDialog()
{
    metRouteValue           = metRoute.value();
    metRouteStopNumValue    = metRouteStopNum.value();
    confirmedShipDateValue  = confirmedShipDate.value();

    return super();
}

public Args parmArgs(Args   _args = args)
{
    args = _args;

    return args;
}

public void run()
{
    METSalesOrderShipmentLoadHeader     metSalesOrderShipmentLoadHeader;
    METSalesOrderShipmentLoadLines      metSalesOrderShipmentLoadLines;
    MultiSelectionHelper                helper = MultiSelectionHelper::construct();
    FormDataSource                      formdataSource;
    SalesTable                          salesTable;
    boolean                             salesTableUpdateFound;

    if (!metRouteValue && !metRouteStopNumValue && !confirmedShipDateValue)
    {
        throw error("Update cancelled as all field value were blank.");
    }

    if (confirmedShipDateValue < DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()))
    {
        throw error("Confirmed ship date cannot be earlier than today.");
    }

    if (args.dataset() == tableNum(METSalesOrderShipmentLoadHeader))
    {
        formdataSource = args.record().dataSource();

        helper.parmDatasource(formdataSource);

        metSalesOrderShipmentLoadHeader = helper.getFirst();

        while (metSalesOrderShipmentLoadHeader.RecId != 0)
        {
            metSalesOrderShipmentLoadHeader.selectForUpdate(true);

            if (metRouteValue)
            {
                metSalesOrderShipmentLoadHeader.Route = metRouteValue;
            }
            if (metRouteStopNumValue)
            {
                metSalesOrderShipmentLoadHeader.RouteStopNum = metRouteStopNumValue;
            }
            if (confirmedShipDateValue)
            {
                metSalesOrderShipmentLoadHeader.ConfirmedShipDate = confirmedShipDateValue;
            }

            //Either one value will always be available, hence not checking for update. Skipping update above if all three are blank.
            metSalesOrderShipmentLoadHeader.update();

            metSalesOrderShipmentLoadHeader.reread();

            while select metSalesOrderShipmentLoadLines
                group by OrderNum
                where metSalesOrderShipmentLoadLines.ShipmentId == metSalesOrderShipmentLoadHeader.ShipmentId
            {
                salesTable = SalesTable::find(metSalesOrderShipmentLoadLines.OrderNum, true);

                if (metRouteValue)
                {
                    salesTable.METRoute = metRouteValue;
                }
                if (metRouteStopNumValue)
                {
                    salesTable.METRouteStopNum = metRouteStopNumValue;
                }
                if (confirmedShipDateValue)
                {
                    salesTable.ShippingDateConfirmed = confirmedShipDateValue;
                }

                //Either one value will always be available, hence not checking for update. Skipping update above if all three are blank.
                salesTable.update();

                METSalesOrderShipmentLoadHeader::createShippmentLoadFromSalesTable(salesTable.SalesId, true, false);
            }


            //salesTable.skipDataMethods(true);

            //update_recordset salesTable
            //    setting ShippingDateConfirmed = confirmedShipDateValue,
            //            METRoute = metRouteValue,
            //            METRouteStopNum = metRouteStopNumValue
            //        exists join metSalesOrderShipmentLoadLines
            //            where metSalesOrderShipmentLoadLines.OrderNum == salesTable.SalesId             &&
            //                metSalesOrderShipmentLoadLines.ShipmentId == metSalesOrderShipmentLoadHeader.ShipmentId;

            //METSalesOrderShipmentLoadHeader::updateLoadStatus(metSalesOrderShipmentLoadHeader.LoadId);

            //tmpTable.clear();

            //tmpTable.RouteStopNum   = metSalesOrderShipmentLoadHeader.RouteStopNum;
            //tmpTable.CustAccount    = metSalesOrderShipmentLoadHeader.CustAccount;
            //tmpTable.ConfirmedShipDate = metSalesOrderShipmentLoadHeader.ConfirmedShipDate;
            //tmpTable.SiteId         = metSalesOrderShipmentLoadHeader.SiteId;
            //tmpTable.Warehouse      = metSalesOrderShipmentLoadHeader.Warehouse;
            //tmpTable.Route          = metSalesOrderShipmentLoadHeader.Route;

            //tmpTable.insert();


            metSalesOrderShipmentLoadHeader = helper.getNext();
        }

       // METSalesOrderShipmentLoadHeader::createShippmentLoadFromTmpTable(tmpTable, true, false);

    }
    else if (args.dataset() == tableNum(METSalesOrderShipmentLoadLines))
    {
        formdataSource = args.record().dataSource();

        helper.parmDatasource(formdataSource);

        metSalesOrderShipmentLoadLines = helper.getFirst();

        salesTable.skipDataMethods(true);

        while (metSalesOrderShipmentLoadLines.RecId != 0)
        {
            salesTable = SalesTable::find(metSalesOrderShipmentLoadLines.OrderNum, true);

            if (metRouteValue)
            {
                salesTable.METRoute = metRouteValue;
            }
            if (metRouteStopNumValue)
            {
                salesTable.METRouteStopNum = metRouteStopNumValue;
            }
            if (confirmedShipDateValue)
            {
                salesTable.ShippingDateConfirmed = confirmedShipDateValue;
            }

            //Either one value will always be available, hence not checking for update. Skipping update above if all three are blank.
            salesTable.update();

            METSalesOrderShipmentLoadHeader::createShippmentLoadFromSalesTable(salesTable.SalesId, true, false);
                //tmpTable.clear();

                //tmpTable.RouteStopNum = salesTable.METRouteStopNum;
                //tmpTable.CustAccount = salesTable.CustAccount;
                //tmpTable.ConfirmedShipDate = salesTable.ShippingDateConfirmed;
                //tmpTable.SiteId = salesTable.InventSiteId;
                //tmpTable.Warehouse = salesTable.InventLocationId;
                //tmpTable.Route = salesTable.METRoute;

                //tmpTable.insert();

            metSalesOrderShipmentLoadLines = helper.getNext();
        }

        //if (salesTableUpdateFound)
        //{
        //    METSalesOrderShipmentLoadHeader::createShippmentLoadFromTmpTable(tmpTable, true, false);
        //}
    }

    info("Update of shipment / load is completed.");
}

public static void main(Args _args)
{
    METShipmentUpdateRoutesDialog metShipmentUpdateRoutesDialog = new METShipmentUpdateRoutesDialog();

    if (metShipmentUpdateRoutesDialog.prompt())
    {
        metShipmentUpdateRoutesDialog.parmArgs(_args);
        metShipmentUpdateRoutesDialog.run();
    }
}
